Definition global_ranked v level states := forall index, (index < 2262)%coq_nat -> (global_rank_at index <= level)%coq_nat -> global_value_at index states = Some (global_target_at index v).
Definition global_port_types states := forall index, (index < 2262)%coq_nat -> global_port_at index = true -> option_map type_of_val (global_value_at index states) = Some (Gtyp (global_type_at index)).
Lemma option_ground_value value ground (typed:option_map type_of_val value = Some (Gtyp ground)) : exists actual, value=Some actual /\ type_of_val actual=Gtyp ground.
Proof. destruct value; [eexists; split; [reflexivity|injection typed; tauto]|discriminate]. Qed.
